/**
 * B19 重叠检测单测（纯函数）
 */
import { describe, expect, test } from 'vitest'
import {
  detectTimeConflicts,
  detectResourceConflicts,
  detectDependencyHubs,
  detectOverlaps,
  type TaskForOverlap,
  type DependencyForOverlap,
} from './overlap-detector'

describe('B19 重叠检测（纯函数）', () => {
  // ===== 维度 1：时间冲突 =====
  describe('时间冲突检测', () => {
    test('空项目：无任务 A0 冲突', () => {
      expect(detectTimeConflicts([])).toHaveLength(0)
    })

    test('单任务：无冲突', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'in_progress' },
      ]
      expect(detectTimeConflicts(tasks)).toHaveLength(0)
    })

    test('两人各一任务，无重叠 → 0 冲突', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
        { id: 't2', title: 'T2', assigneeId: 'u2', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
      ]
      expect(detectTimeConflicts(tasks)).toHaveLength(0)
    })

    test('同一人两任务完全重叠 5 天 → high 严重度', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: '任务 A', assigneeId: 'u1', assigneeName: '张三', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'in_progress' },
        { id: 't2', title: '任务 B', assigneeId: 'u1', assigneeName: '张三', start: '2026-08-18', end: '2026-08-22', estimatedHours: 20, status: 'todo' },
      ]
      const result = detectTimeConflicts(tasks)
      expect(result).toHaveLength(1)
      expect(result[0].overlapDays).toBe(5)
      expect(result[0].severity).toBe('high')
      expect(result[0].taskIds).toEqual(expect.arrayContaining(['t1', 't2']))
      expect(result[0].assigneeName).toBe('张三')
    })

    test('同一人两任务部分重叠 2 天 → medium 严重度', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'A', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-20', estimatedHours: 24, status: 'todo' },
        { id: 't2', title: 'B', assigneeId: 'u1', start: '2026-08-20', end: '2026-08-22', estimatedHours: 24, status: 'todo' },
      ]
      const result = detectTimeConflicts(tasks)
      expect(result).toHaveLength(1)
      expect(result[0].overlapDays).toBe(1) // 8-20 当天算 1 天
      expect(result[0].severity).toBe('low')
    })

    test('三任务两两重任务 A合并为 1 组（并查集）', () => {
      // t1: 18-22, t2: 20-24, t3: 22-26 → 都和至少一个重叠
      // 但 t1 和 t3 只在 22 号交接，算 1 天重叠（t1.end=22, t3.start=22）
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 32, status: 'todo' },
        { id: 't2', title: 'T2', assigneeId: 'u1', start: '2026-08-20', end: '2026-08-24', estimatedHours: 32, status: 'todo' },
        { id: 't3', title: 'T3', assigneeId: 'u1', start: '2026-08-22', end: '2026-08-26', estimatedHours: 32, status: 'todo' },
      ]
      const result = detectTimeConflicts(tasks)
      expect(result).toHaveLength(1)
      expect(result[0].taskIds).toHaveLength(3)
      expect(result[0].taskIds).toEqual(expect.arrayContaining(['t1', 't2', 't3']))
    })

    test('已完成任务不参与冲突检测', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'A', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'done' },
        { id: 't2', title: 'B', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
      ]
      expect(detectTimeConflicts(tasks)).toHaveLength(0)
    })
  })

  // ===== 维度 2：资源争抢 =====
  describe('资源争抢检测', () => {
    test('空项目 → 0 争抢', () => {
      expect(detectResourceConflicts([])).toHaveLength(0)
    })

    test('单任务 8h/天（5天40h）→ 恰等于阈值，不争抢', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
      ]
      const result = detectResourceConflicts(tasks, 8)
      expect(result).toHaveLength(0)
    })

    test('日估时 10h > 8h → low 严重度', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 50, status: 'todo' }, // 50/5=10h/天
      ]
      const result = detectResourceConflicts(tasks, 8)
      expect(result.length).toBeGreaterThanOrEqual(1)
      expect(result[0].severity).toBe('low')
      expect(result[0].taskCount).toBe(1)
    })

    test('日估时 16h > 8h → high 严重度（ratio=2.0 > 1.8）', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
        { id: 't2', title: 'T2', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
      ]
      const result = detectResourceConflicts(tasks, 8)
      expect(result.length).toBe(5) // 5 天全部争抢      expect(result[0].severity).toBe('high')
      expect(result[0].totalHours).toBeCloseTo(16, 1)
    })

    test('不同人的任务不叠加', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
        { id: 't2', title: 'T2', assigneeId: 'u2', start: '2026-08-18', end: '2026-08-22', estimatedHours: 40, status: 'todo' },
      ]
      const result = detectResourceConflicts(tasks, 8)
      expect(result).toHaveLength(0)
    })

    test('阈值可调：设阈值 12h → 原 10h/天 不争抢', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 50, status: 'todo' },
      ]
      const result = detectResourceConflicts(tasks, 12)
      expect(result).toHaveLength(0)
    })
  })

  // ===== 维度 3：依赖交汇 =====
  describe('依赖交汇检测', () => {
    test('无依赖 → 0 hub', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: 'T1', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-22', estimatedHours: 8, status: 'todo' },
      ]
      expect(detectDependencyHubs(tasks, [])).toHaveLength(0)
    })

    test('is_shared=false 的依赖不参与', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: '前置', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-19', estimatedHours: 8, status: 'todo' },
        { id: 't2', title: '下游A', assigneeId: 'u2', start: '2026-08-20', end: '2026-08-22', estimatedHours: 16, status: 'todo' },
        { id: 't3', title: '下游B', assigneeId: 'u3', start: '2026-08-20', end: '2026-08-22', estimatedHours: 24, status: 'todo' },
      ]
      const deps: DependencyForOverlap[] = [
        { id: 'd1', prevTaskId: 't1', nextTaskId: 't2', isShared: false, type: 'FS' },
        { id: 'd2', prevTaskId: 't1', nextTaskId: 't3', isShared: false, type: 'FS' },
      ]
      expect(detectDependencyHubs(tasks, deps)).toHaveLength(0)
    })

    test('1 个共享前置 + 2 下游 → 1 hub，benefitScore = 2 × 平均估时', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: '共享前置', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-19', estimatedHours: 8, status: 'todo' },
        { id: 't2', title: '下游A', assigneeId: 'u2', start: '2026-08-20', end: '2026-08-22', estimatedHours: 16, status: 'todo' },
        { id: 't3', title: '下游B', assigneeId: 'u3', start: '2026-08-20', end: '2026-08-22', estimatedHours: 24, status: 'todo' },
      ]
      const deps: DependencyForOverlap[] = [
        { id: 'd1', prevTaskId: 't1', nextTaskId: 't2', isShared: true, type: 'FS' },
        { id: 'd2', prevTaskId: 't1', nextTaskId: 't3', isShared: true, type: 'FS' },
      ]
      const result = detectDependencyHubs(tasks, deps)
      expect(result).toHaveLength(1)
      expect(result[0].downstreamCount).toBe(2)
      // 平均估时 = (16+24)/2 = 20; benefit = 2 × 20 = 40
      expect(result[0].benefitScore).toBe(40)
    })

    test('单下游共享不算 hub（需 ≥2）', () => {
      const tasks: TaskForOverlap[] = [
        { id: 't1', title: '张三', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-19', estimatedHours: 8, status: 'todo' },
        { id: 't2', title: '前置', assigneeId: 'u2', start: '2026-08-20', end: '2026-08-22', estimatedHours: 16, status: 'todo' },
      ]
      const deps: DependencyForOverlap[] = [
        { id: 'd1', prevTaskId: 't1', nextTaskId: 't2', isShared: true, type: 'FS' },
      ]
      expect(detectDependencyHubs(tasks, deps)).toHaveLength(0)
    })

    test('多个 hub 按 benefitScore 降序排列', () => {
      const tasks: TaskForOverlap[] = [
        { id: 'h1', title: '小hub', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-19', estimatedHours: 4, status: 'todo' },
        { id: 'h2', title: '大hub', assigneeId: 'u2', start: '2026-08-18', end: '2026-08-20', estimatedHours: 16, status: 'todo', isOnCriticalPath: true },
        { id: 'a1', title: 'A1', assigneeId: 'u3', start: '2026-08-20', end: '2026-08-22', estimatedHours: 8, status: 'todo' },
        { id: 'a2', title: 'A2', assigneeId: 'u4', start: '2026-08-20', end: '2026-08-22', estimatedHours: 8, status: 'todo' },
        { id: 'b1', title: 'B1', assigneeId: 'u3', start: '2026-08-21', end: '2026-08-23', estimatedHours: 16, status: 'todo' },
        { id: 'b2', title: 'B2', assigneeId: 'u4', start: '2026-08-21', end: '2026-08-23', estimatedHours: 16, status: 'todo' },
        { id: 'b3', title: 'B3', assigneeId: 'u5', start: '2026-08-21', end: '2026-08-23', estimatedHours: 16, status: 'todo' },
      ]
      const deps: DependencyForOverlap[] = [
        { id: 'd1', prevTaskId: 'h1', nextTaskId: 'a1', isShared: true, type: 'FS' },
        { id: 'd2', prevTaskId: 'h1', nextTaskId: 'a2', isShared: true, type: 'FS' },
        { id: 'd3', prevTaskId: 'h2', nextTaskId: 'b1', isShared: true, type: 'FS' },
        { id: 'd4', prevTaskId: 'h2', nextTaskId: 'b2', isShared: true, type: 'FS' },
        { id: 'd5', prevTaskId: 'h2', nextTaskId: 'b3', isShared: true, type: 'FS' },
      ]
      const result = detectDependencyHubs(tasks, deps)
      expect(result).toHaveLength(2)
      expect(result[0].hubTaskId).toBe('h2') // benefit = 3 * 16 = 48
      expect(result[1].hubTaskId).toBe('h1') // benefit = 2 * 8 = 16
      expect(result[0].isOnCriticalPath).toBe(true)
    })
  })

  // ===== 综合 =====
  describe('综合检测', () => {
    const tasks: TaskForOverlap[] = [
      { id: 't1', title: '共享前置', assigneeId: 'u1', start: '2026-08-18', end: '2026-08-19', estimatedHours: 8, status: 'todo' },
      { id: 't2', title: '任务A', assigneeId: 'u2', start: '2026-08-20', end: '2026-08-22', estimatedHours: 16, status: 'todo' },
      { id: 't3', title: '任务B', assigneeId: 'u2', start: '2026-08-20', end: '2026-08-22', estimatedHours: 24, status: 'todo' },
      { id: 't4', title: '任务C', assigneeId: 'u3', start: '2026-08-20', end: '2026-08-22', estimatedHours: 24, status: 'todo' },
    ]
    const deps: DependencyForOverlap[] = [
      { id: 'd1', prevTaskId: 't1', nextTaskId: 't2', isShared: true, type: 'FS' },
      { id: 'd2', prevTaskId: 't1', nextTaskId: 't3', isShared: true, type: 'FS' },
      { id: 'd3', prevTaskId: 't1', nextTaskId: 't4', isShared: true, type: 'FS' },
    ]

    test('综合：三维度全开，结果正确', () => {
      const result = detectOverlaps('p1', tasks, deps)
      expect(result.projectId).toBe('p1')
      // 时间冲突：u2 有 t2+t3 重叠
      expect(result.summary.timeConflicts).toBe(1)
      // 资源争抢：u2 每天 (16+24)/3 ≈ 13.3h > 8
      expect(result.summary.resourceConflicts).toBeGreaterThan(0)
      // 依赖交汇：t1 有 3 下游
      expect(result.summary.dependencyHubs).toBe(1)
      expect(result.summary.totalAffectedTasks).toBeGreaterThan(0)
    })

    test('综合严重度：有 high 项 → high', () => {
      // u2 t2(16h/3天=5.3) + t3(24h/3天=8) = 13.3/天, ratio=1.66 → medium
      // 依赖交汇 benefit = 3 * (16+24+24)/3 = 64 → ≥40 → high
      const result = detectOverlaps('p1', tasks, deps)
      expect(result.summary.severity).toBe('high')
    })

    test('只跑指定维度：只跑 time → resource/dependency 为空', () => {
      const result = detectOverlaps('p1', tasks, deps, { dimensions: ['time'] })
      expect(result.dimensions.time.length).toBeGreaterThan(0)
      expect(result.dimensions.resource).toHaveLength(0)
      expect(result.dimensions.dependency).toHaveLength(0)
    })

    test('空数据 → 全 0 + low 严重度', () => {
      const result = detectOverlaps('p1', [], [])
      expect(result.summary.timeConflicts).toBe(0)
      expect(result.summary.resourceConflicts).toBe(0)
      expect(result.summary.dependencyHubs).toBe(0)
      expect(result.summary.totalAffectedTasks).toBe(0)
      expect(result.summary.severity).toBe('low')
    })
  })
})
